// EDIT THIS LIST -- these are the pages callscout crawls for call-like links.
// callscout ships with no hardcoded seed list on purpose (see its README): only
// point it at pages you already know announce or list funding calls -- a
// funder's own "open calls" page, an NGO grants directory, a DFI's RFP index.
const SEED_URLS = [
  "https://example-funder.org/open-calls",
  "https://example-directory.org/grants"
];

const knownUrls = $input.all()
  .map(item => item.json.url)
  .filter(Boolean);

return [{
  json: {
    seed_urls: SEED_URLS,
    known_urls: knownUrls,
    max_links_per_seed: 30,
    only_same_domain: false,
    use_llm_fallback: true
  }
}];

