// Anthropic's response is $json.content[0].text -- a JSON object as a string
// (the system prompt asks for ONLY that, no markdown fences, but we strip
// fences defensively in case the model adds them anyway).
const orig = $('Looks Like Call?').item.json;

let cls = {};
let classification_failed = false;
try {
  const raw = ($json.content && $json.content[0] && $json.content[0].text) || '';
  const cleaned = raw.trim().replace(/^```(json)?/i, '').replace(/```$/, '').trim();
  cls = JSON.parse(cleaned);
} catch (err) {
  classification_failed = true;
  cls = {
    name: orig.title || orig.source_url,
    issuing_org: '',
    eligible_geography: '',
    eligible_applicant_type: '',
    instrument_type: '',
    sector_focus: '',
    eligibility_summary: 'Classification failed -- review manually. ' + String(err),
    relevance_score: '',
    is_lac: false,
    status_signal: ''
  };
}

return {
  json: {
    url: orig.source_url,
    opening_date: orig.opening_date,
    deadline: orig.deadline,
    amount_range: orig.amount_range,
    field_confidence: orig.field_confidence,
    discovered_via_seed: orig.discovered_via_seed,
    looks_like_call: orig.looks_like_call,
    name: cls.name || orig.title || orig.source_url,
    issuing_org: cls.issuing_org || '',
    eligible_geography: cls.eligible_geography || '',
    eligible_applicant_type: cls.eligible_applicant_type || '',
    instrument_type: cls.instrument_type || '',
    sector_focus: cls.sector_focus || '',
    eligibility_summary: cls.eligibility_summary || '',
    relevance_score: cls.relevance_score !== undefined ? cls.relevance_score : '',
    is_lac: !!cls.is_lac,
    status_signal: cls.status_signal || '',
    classification_failed
  }
};

const j = $input.item.json;
const raw = (j.deadline || '').toString().trim();
const parsed = raw ? new Date(raw) : null;
const isValidDate = parsed && !isNaN(parsed.getTime());

let deadline_display, days_to_deadline, deadline_was_estimated;

if (isValidDate) {
  deadline_display = raw;
  days_to_deadline = Math.ceil((parsed - new Date()) / 86400000);
  deadline_was_estimated = false;
} else if (raw) {
  deadline_display = raw;
  days_to_deadline = null;
  deadline_was_estimated = false;
} else {
  deadline_display = 'Not specified';
  days_to_deadline = null;
  deadline_was_estimated = true;
}

const signal = (j.status_signal || '').toLowerCase();
let status = 'open';
if (signal.includes('closed')) {
  status = 'closed';
} else if (days_to_deadline !== null && days_to_deadline < 0) {
  status = 'closed';
}

return { json: { ...j, deadline_display, days_to_deadline, deadline_was_estimated, status,
  date_added: new Date().toISOString().slice(0, 10), digest_sent: 'false' } };

const seen = new Set();
return $input.all().filter(item => {
  const j = item.json;
  if (!j.name || !j.url) return false;
  const sentVal = (j.digest_sent || '').toString().toLowerCase().trim();
  if (sentVal === 'true') return false;
  const statusVal = (j.status || '').toString().toLowerCase().trim();
  if (statusVal === 'closed') return false;
  if (seen.has(j.url)) return false;
  seen.add(j.url);
  return true;
});

const items = $input.all();

function hasCompleteInfo(j) {
  const hasDate = !j.deadline_was_estimated && j.deadline_display && j.deadline_display !== 'Not specified';
  const hasScore = j.relevance_score !== undefined && j.relevance_score !== null && j.relevance_score !== '';
  return hasDate && hasScore;
}

items.sort((a, b) => {
  const aComplete = hasCompleteInfo(a.json) ? 1 : 0;
  const bComplete = hasCompleteInfo(b.json) ? 1 : 0;
  if (bComplete - aComplete !== 0) return bComplete - aComplete;

  const aScore = Number(a.json.relevance_score) || 0;
  const bScore = Number(b.json.relevance_score) || 0;
  if (bScore - aScore !== 0) return bScore - aScore;

  const aDeadline = (a.json.days_to_deadline === null || a.json.days_to_deadline === '') ? Infinity : Number(a.json.days_to_deadline);
  const bDeadline = (b.json.days_to_deadline === null || b.json.days_to_deadline === '') ? Infinity : Number(b.json.days_to_deadline);
  return aDeadline - bDeadline;
});

return items;

const items = $input.all();
if (items.length === 0) return [];

const rows = items.map(item => {
  const j = item.json;
  const deadlineLabel = j.deadline_was_estimated
    ? '<span style="color:#999;">Not specified</span>'
    : (j.deadline_display || j.deadline || 'Not specified');
  const isClosed = j.status === 'closed';
  const rowStyle = isClosed ? 'style="color:#999;text-decoration:line-through;"' : '';
  return `<tr ${rowStyle}>
    <td>${j.name || ''}</td>
    <td>${j.issuing_org || ''}</td>
    <td>${deadlineLabel}</td>
    <td>${j.instrument_type || ''}</td>
    <td>${j.relevance_score || '—'}</td>
    <td>${j.status || 'open'}</td>
    <td><a href="${j.url}">Link</a></td>
  </tr>`;
}).join('\n');

const html = `<h3>Urgent: Closing Within 2 Weeks (${items.length})</h3>
<table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse;">
<tr><th>Name</th><th>Org</th><th>Deadline</th><th>Instrument</th><th>Score</th><th>Status</th><th>Link</th></tr>
${rows}
</table>`;

return [{ json: { emailHtml: html } }];

